return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'hr','project-id-version'=>'babilim-0.1.0-hr-babilim-0.1.0-hr-20261030T024819','pot-creation-date'=>'2026-10-30T06:25:28+00:00','po-revision-date'=>'2026-10-30T06:25:28+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Popunjava nedostajuće prijevode za dodatke i teme koji su već instalirani na vašoj web-stranici.','Translations'=>'Prijevodi','Babilim Settings'=>'Postavke Babilima','Settings'=>'Postavke','You are not allowed to do this.'=>'Nemate dopuštenje za ovu radnju.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Odaberite manje komponenti: najviše %1$d operacija po pokretanju (odabrali ste ih %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Ta komponenta nije instalirana na ovoj web-stranici, pa za nju nije moguće zatražiti prijevod.','Already installed.'=>'Već je instalirano.','Downloaded and installed.'=>'Preuzeto i instalirano.','Babilim has not been enabled for this site yet.'=>'Babilim još nije omogućen za ovu web-stranicu.','No build is available to download for this locale.'=>'Za ovaj jezik nije dostupan nijedan build za preuzimanje.','Rolled back to the previous build.'=>'Vraćeno na prethodni build.','Rolled back and reported.'=>'Vraćeno na prethodno i prijavljeno.','Rolled back, but the report could not be sent: %s'=>'Vraćeno na prethodno, ali prijavu nije bilo moguće poslati: %s','Removed.'=>'Uklonjeno.','Translation requested.'=>'Prijevod je zatražen.','This component was already uploaded. Babilim is checking it now.'=>'Ta je komponenta već učitana. Babilim je upravo provjerava.','Upload cancelled.'=>'Učitavanje je otkazano.','Upload complete — translation requested.'=>'Učitavanje je dovršeno — prijevod je zatražen.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Ova komponenta ne navodi broj verzije, pa za nju nije moguće zatražiti prijevod.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Broj verzije ove komponente dulji je od %d znakova, što Babilim ne može obraditi, pa za nju nije moguće zatražiti prijevod.','A translation cannot be requested for that locale on this site right now.'=>'Za taj jezik trenutačno nije moguće zatražiti prijevod na ovoj web-stranici.','Thank you. Your report was sent.'=>'Hvala. Vaša prijava je poslana.','This report does not name a valid plugin or theme and locale.'=>'Ova prijava ne navodi valjan dodatak ili temu i jezik.','Please choose a category for this report.'=>'Odaberite kategoriju za ovu prijavu.','This report is missing a valid build to report against.'=>'Ovoj prijavi nedostaje valjan build na koji se odnosi.','This build is not one this site currently knows about for this component/locale.'=>'Ovaj build nije jedan od onih koje ova web-stranica trenutačno poznaje za ovu komponentu/jezik.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Polje "%1$s" je predugo: ima %2$d znakova, a ograničenje je %3$d. Ništa nije poslano; skratite ga i pokušajte ponovno.','Original string'=>'Izvorni niz','String context'=>'Kontekst niza','Current translation'=>'Trenutni prijevod','Suggested translation'=>'Predloženi prijevod','Note (optional)'=>'Napomena (neobavezno)','Where you saw this (optional)'=>'Gdje ste to vidjeli (neobavezno)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim sinkronizacija privremeno je odgođena od strane usluge (ograničenje broja zahtjeva); pokušat će ponovno nakon %s.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'Dodani jezik nije valjan: upotrijebite WordPress kod jezika poput ll_CC (slova, znamenke, podvlaka, crtica ili @, najviše %d znakova). Ništa nije spremljeno.','Settings saved.'=>'Postavke su spremljene.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ako je ovo uključeno, deinstalacija briše i identitet ove web-stranice. Plaćena licenca povezana s ovom web-stranicom poslije se ne može automatski vratiti; za povrat morat ćete kontaktirati Babilim podršku na %s.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim je postavljen da obriše identitet ove web-stranice kada se dodatak izbriše. Plaćena licenca povezana s ovom web-stranicom tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %s. Da biste zadržali identitet, pritisnite Odustani, isključite "Obriši sve podatke Babilima prilikom deinstalacije" u postavkama Babilima i ponovno deaktivirajte. Želite li ipak deaktivirati?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d web-stranica na ovoj mreži postavljena je da obriše svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca povezana s tom web-stranicom tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da biste zadržali identitet, pritisnite Odustani, isključite "Obriši sve podatke Babilima prilikom deinstalacije" u Babilim postavkama te web-stranice i ponovno deaktivirajte. Želite li ipak deaktivirati?' . "\0" . '%1$d web-stranice na ovoj mreži postavljene su da obrišu svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca povezana s tim web-stranicama tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da biste zadržali identitete, pritisnite Odustani, isključite "Obriši sve podatke Babilima prilikom deinstalacije" u Babilim postavkama svake web-stranice i ponovno deaktivirajte. Želite li ipak deaktivirati?' . "\0" . '%1$d web-stranica na ovoj mreži postavljeno je da obrišu svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca povezana s tim web-stranicama tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da biste zadržali identitete, pritisnite Odustani, isključite "Obriši sve podatke Babilima prilikom deinstalacije" u Babilim postavkama svake web-stranice i ponovno deaktivirajte. Želite li ipak deaktivirati?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ova mreža ima previše web-stranica da bi se provjeravale jedna po jedna, a neke od njih možda su postavljene da izbrišu svoj Babilim identitet kad se dodatak izbriše. Plaćena licenca vezana uz takvu web-stranicu tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %s. Da biste sačuvali identitete, pritisnite Odustani, poništite opciju "Obriši sve podatke Babilima prilikom deinstalacije" u Babilim postavkama svake web-stranice i ponovno deaktivirajte. Ipak deaktivirati?','Open Babilim settings'=>'Otvori Babilim postavke','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nije mogao provjeriti ovu web-stranicu, pa se ništa ne preuzima niti instalira.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Usluga nije mogla doprijeti do vaše web-stranice. Vjerojatno zahtjev blokira vatrozid, sigurnosni dodatak ili pravilo poslužitelja; dopustite zahtjeve na /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Vaša web-stranica je predugo odgovarala. Pokušajte ponovno kasnije i provjerite nije li vaš poslužitelj prespor ili preopterećen.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Vaša web-stranica je odgovorila, ali ne onim što se očekivalo. REST API možda prepisuje drugi dodatak ili je ta krajnja točka u predmemoriji; izuzmite /wp-json/babilim/v1/challenge iz predmemoriranja i prepisivanja.','Please check that your site can be reached from the internet, then try again.'=>'Provjerite je li vaša web-stranica dostupna s interneta, pa pokušajte ponovno.','Re-verify'=>'Ponovno provjeri','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Ova web-stranica premašuje veličinu koju usluga prihvaća u jednoj sinkronizaciji, pa su neke stavke izostavljene: komponenti: %1$d i jezika: %2$d.','This site is verified.'=>'Ova web-stranica je provjerena.','Registration restarted.'=>'Registracija je ponovno pokrenuta.','Sync complete.'=>'Sinkronizacija je dovršena.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim omogućuje i provjerava ovu web-stranicu… Ponovno učitajte stranicu ili pričekajte da završi zakazana provjera.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nije mogao dovršiti omogućivanje (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Poslužitelj koji istodobno obrađuje samo jedan PHP zahtjev ne može dovršiti ovaj korak.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim je omogućen: ova web-stranica je provjerena i pronađena je %d komponenta.' . "\0" . 'Babilim je omogućen: ova web-stranica je provjerena i pronađene su %d komponente.' . "\0" . 'Babilim je omogućen: ova web-stranica je provjerena i pronađeno je %d komponenti.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim je onemogućen. Ništa se više ne šalje; već instalirani prijevodi nastavljaju raditi.','Supplementary translation index rebuilt.'=>'Dopunski indeks prijevoda je ponovno izgrađen.','Sweep complete: %d file deleted.'=>'Pretraživanje dovršeno: izbrisana je %d datoteka.' . "\0" . 'Pretraživanje dovršeno: izbrisane su %d datoteke.' . "\0" . 'Pretraživanje dovršeno: izbrisano je %d datoteka.','Removed %d installed component.'=>'Uklonjena je %d instalirana komponenta.' . "\0" . 'Uklonjene su %d instalirane komponente.' . "\0" . 'Uklonjeno je %d instaliranih komponenti.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automatske instalacije sada su isključene; ponovno ih uključite u postavkama ako ih želite.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim pronalazi dodatke i teme na ovoj web-stranici koji nemaju prijevod za vaš jezik i instalira jedan za svaki.','Languages found on this site: %s.'=>'Jezici pronađeni na ovoj web-stranici: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Dostupni prijevodi mogu se instalirati jednim klikom, a nedostajući se mogu zatražiti. Nakon toga novi se prijevodi i ažuriranja instaliraju automatski (u besplatnom paketu samo za dodatke i teme koji već koriste besplatno mjesto).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Besplatni paket pokriva ograničen broj dodataka i tema; vaša točna kvota prikazana je u Postavkama nakon što omogućite Babilim.','What is sent when you enable Babilim'=>'Što se šalje kad omogućite Babilim','Enabling…'=>'Omogućivanje…','Enable Babilim'=>'Omogući Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Klikom na Omogući pristajete poslati gore navedene podatke Babilimu.','Check again now'=>'Provjeri ponovno sada','Babilim installed %d translation automatically since your last visit.'=>'Babilim je automatski instalirao %d prijevod od vašeg posljednjeg posjeta.' . "\0" . 'Babilim je automatski instalirao %d prijevoda od vašeg posljednjeg posjeta.' . "\0" . 'Babilim je automatski instalirao %d prijevoda od vašeg posljednjeg posjeta.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim omogućuje i provjerava ovu web-stranicu… (posljednji pokušaj: %s)','Check again'=>'Provjeri ponovno','No components synced yet.'=>'Još nema sinkroniziranih komponenti.','%d succeeded'=>'%d uspjelo' . "\0" . '%d uspjelo' . "\0" . '%d uspjelo','%d skipped'=>'%d preskočeno' . "\0" . '%d preskočeno' . "\0" . '%d preskočeno','%d failed'=>'%d nije uspjelo' . "\0" . '%d nije uspjelo' . "\0" . '%d nije uspjelo','%d not yet tried'=>'%d još nije pokušano' . "\0" . '%d još nije pokušano' . "\0" . '%d još nije pokušano','Bulk %s:'=>'Skupno %s:','%1$s nothing to do.'=>'%1$s nema ništa za učiniti.','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Nastavlja se…','Continue next batch (%d left)'=>'Nastavi sa sljedećom skupinom (preostalo: %d)','Search components'=>'Pretraži komponente','These are the languages this site uses. You can change them in %s.'=>'Ovo su jezici koje ova web-stranica koristi. Možete ih promijeniti u %s.','Upload this component?'=>'Učitati ovu komponentu?','There is no upload waiting for confirmation.'=>'Nema učitavanja koje čeka potvrdu.','Back'=>'Natrag','To translate this component, Babilim needs its source.'=>'Za prevođenje ove komponente Babilimu je potreban njezin izvorni kod.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Cijeli direktorij dodatka ili teme %1$s (verzija %2$s) bit će učitan na Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Ako taj direktorij sadrži ključeve, zapisnike ili podatke o korisnicima, i oni će biti učitani. Usluga uklanja uobičajene osjetljive datoteke (konfiguraciju, okruženje, izvoze baze podataka, zapisnike, ključeve), ali ne može jamčiti da će pronaći sve.','The upload is kept until you ask Babilim to delete it.'=>'Učitani sadržaj čuva se dok od Babilima ne zatražite da ga izbriše.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Pohranjuje ga pružatelj hostinga usluge, a AI modeli ga obrađuju kako bi izradili prijevod.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Izvorni tekst i prijevodi izrađeni iz njega bit će dostupni drugim web-stranicama koje instaliraju istu verziju.','By continuing you confirm that you have the right to upload this component.'=>'Nastavkom potvrđujete da imate pravo učitati ovu komponentu.','Upload and request'=>'Učitaj i zatraži','Uploading…'=>'Učitavanje…','Cancel'=>'Odustani','Uploading'=>'Učitavanje','There is no upload in progress.'=>'Nema učitavanja u tijeku.','Uploading part %1$d of %2$d…'=>'Učitavanje dijela %1$d od %2$d…','Continue'=>'Nastavi','Confirm'=>'Potvrdi','Remove'=>'Ukloni','Roll back'=>'Vrati na prethodno','Nothing to confirm.'=>'Nema ništa za potvrditi.','Choose a language'=>'Odaberite jezik','Roll back and report'=>'Vrati na prethodno i prijavi','Report a problem'=>'Prijavi problem','Nothing to choose.'=>'Nema ništa za odabrati.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Odaberite jezik.','Supplementary translations'=>'Dopunski prijevodi','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Doprinos svake komponente zajedničkom dopunskom prijevodu zadane domene za pojedini jezik.','Component'=>'Komponenta','Language'=>'Jezik','Included in index'=>'Uključeno u indeks','Entries'=>'Unosi','Conflicting keys'=>'Ključevi u sukobu','Yes'=>'Da','No — component inactive'=>'Ne – komponenta nije aktivna','No — installed version differs from the active one'=>'Ne – instalirana verzija razlikuje se od aktivne','No — component removed'=>'Ne – komponenta je uklonjena','No'=>'Ne','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Ovo može učiniti samo administrator mreže jer se mijenjaju datoteke prijevoda koje dijele sve web-stranice u ovoj mreži.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nije mogao dovršiti provjeru ove web-stranice (usluga nije mogla uspostaviti vezu s njom). Registracija je pauzirana.','This site already has an active registration that can no longer be recovered automatically.'=>'Ova web-stranica već ima aktivnu registraciju koja se više ne može automatski oporaviti.','Restart registration'=>'Ponovno pokreni registraciju','Babilim settings'=>'Postavke Babilima','General'=>'Općenito','Advanced'=>'Napredno','Languages'=>'Jezici','Automatic installs'=>'Automatske instalacije','Install available translations automatically'=>'Automatski instaliraj dostupne prijevode','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'U besplatnom paketu automatski se instaliraju samo komponente koje već koriste jedno od vaših slobodnih mjesta, pa se nijedno novo mjesto ne zauzima.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Ova web-stranica dio je multisite mreže, koja ne instalira automatski nove prijevode. Već instalirani prijevodi i dalje se ažuriraju.','Custom overrides'=>'Prilagođena nadjačavanja','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Zadrži moja vlastita nadjačavanja prijevoda pri brisanju svega ili deinstalaciji ovog dodatka.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Datoteke prijevoda koje postavite u %s uvijek imaju prednost pred Babilimovima. Zadržavaju se osim ako ovo isključite.','Uninstall'=>'Deinstalacija','Delete all Babilim data on uninstall'=>'Obriši sve podatke Babilima prilikom deinstalacije','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Prema zadanim postavkama isključeno: brisanjem dodatka identitet ove web-stranice se zadržava, pa ga ponovna instalacija može ponovno upotrijebiti.','Account'=>'Račun','Save changes'=>'Spremi promjene','Disable Babilim'=>'Onemogući Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Instalirani prijevodi se zadržavaju, ali se više neće izvoditi provjere ni preuzimanja.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Onemogućiti Babilim? Instalirani prijevodi se zadržavaju, ali se više neće izvoditi provjere ni preuzimanja.','This site is not registered with Babilim yet.'=>'Ova web-stranica još nije registrirana u Babilimu.','This site is already licensed. Reload the page.'=>'Ova web-stranica već ima licencu. Ponovno učitajte stranicu.','Checkout is not available for this site right now.'=>'Blagajna trenutačno nije dostupna za ovu web-stranicu.','Could not start checkout: %s'=>'Nije moguće pokrenuti blagajnu: %s','Babilim is not enabled.'=>'Babilim nije omogućen.','Not registered yet'=>'Još nije registrirano','Not verified'=>'Nije provjereno','Verified'=>'Provjereno','Status'=>'Status','Licensed'=>'Licencirano','Partner'=>'Partner','Free'=>'Besplatno','License'=>'Licenca','Upgrade this site'=>'Nadogradi ovu web-stranicu','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Jednokratna kupnja za ovu web-stranicu: %1$s %2$s. Uključuje sva buduća ažuriranja prijevoda. Plaćanjem upravlja Paddle u novoj kartici.','This issues a new restore code and the previous one stops working. Continue?'=>'Ovime se izdaje novi kod za vraćanje, a prethodni prestaje vrijediti. Nastaviti?','Show a new restore code'=>'Prikaži novi kod za vraćanje','rc_…'=>'rc_…','Restore code'=>'Kod za vraćanje','Restore purchase'=>'Vrati kupnju','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Jeste li već kupili licencu za ovu domenu? Unesite kod za vraćanje koji ste primili na blagajni.','That does not look like a restore code.'=>'Ovo ne izgleda kao kod za vraćanje.','This restore code was not recognised for this site.'=>'Ovaj kod za vraćanje nije prepoznat za ovu web-stranicu.','Too many attempts. Try again tomorrow.'=>'Previše pokušaja. Pokušajte ponovno sutra.','This site must be verified first.'=>'Ova web-stranica prvo mora biti provjerena.','Could not restore the purchase: %s'=>'Kupnju nije moguće vratiti: %s','Purchase restored. This site is now licensed.'=>'Kupnja je vraćena. Ova web-stranica sada je licencirana.','This site has no purchase to show a code for.'=>'Ova web-stranica nema kupnju za koju bi se prikazao kod.','Could not show a new restore code: %s'=>'Nije moguće prikazati novi kod za vraćanje: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Vaš novi kod za vraćanje: %s. Spremite ga na sigurno mjesto — prethodni kod više ne vrijedi.','What is sent when Babilim checks this site'=>'Što se šalje kada Babilim provjerava ovu web-stranicu','(detected)'=>'(otkriveno)','No language is managed yet.'=>'Još se ne upravlja nijednim jezikom.','Babilim adds translations for every language checked here.'=>'Babilim dodaje prijevode za svaki ovdje označeni jezik.','Add another language'=>'Dodaj još jedan jezik','Choose a language…'=>'Odaberite jezik…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Nije moguće učitati cjelovit popis jezika s WordPress.org s usluge pa trenutačno nije moguće dodati nijedan drugi jezik.','Theme'=>'Tema','Plugin'=>'Dodatak','Free quota'=>'Besplatna kvota','Downloads: %1$d/%2$d (%3$s)'=>'Preuzimanja: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Dopunski indeks prijevoda','Built'=>'Izgrađeno','Included'=>'Uključeno','Excluded'=>'Isključeno','Already in WordPress core'=>'Već u jezgri WordPressa','Supplementary translation maintenance'=>'Održavanje dopunskih prijevoda','Maintenance status is not available right now.'=>'Status održavanja trenutačno nije dostupan.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Čišćenje je pauzirano %1$s: %2$s. Ništa nije izbrisano.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Posljednje čišćenje: %1$s: %2$d novooznačeno, %3$d datoteka izbrisano, %4$d zapisa uklonjeno.','No cleanup has run yet.'=>'Čišćenje još nije pokrenuto.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Pisanje u indeks prijevoda sukobilo se s drugim zahtjevom na %1$s (%2$s) i nije primijenjeno; zadržana je najnovija verzija.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Pisanje u indeks prijevoda na %1$s (%2$s) nije moglo biti dovršeno i nije primijenjeno (%3$s).','Maintenance'=>'Održavanje','Rebuild index now'=>'Ponovno izgradi indeks sada','Sweep now'=>'Pretraži sada','Danger zone'=>'Opasna zona','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Uklanja svaku jezičnu datoteku koju je Babilim instalirao za sve dodatke i teme na ovoj web-stranici. Jezik','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Ukloniti sve što je Babilim instalirao? Time se brišu sve datoteke jezika koje je Babilim instalirao za sve dodatke i teme na ovoj web-stranici.','Remove everything Babilim installed'=>'Ukloniti sve što je Babilim instalirao','This string is too long to be sent as a report, so no report form is offered for it.'=>'Ovaj je niz predug za slanje u izvješću, pa se za njega ne nudi obrazac za izvješće.','Category'=>'Kategorija','Choose a category…'=>'Odaberite kategoriju…','Roll back and send report'=>'Vrati i pošalji izvješće','Send report'=>'Pošalji izvješće','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Dio teksta ove komponente autor je izravno upisao u kod pa ga jezični paket ne može prevesti.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Isporučeno s temom','Bundled with the plugin'=>'Isporučeno s dodatkom','Upload was not accepted'=>'Prijenos nije prihvaćen','Upload expired before it finished'=>'Prijenos je istekao prije dovršetka','No translation'=>'Nema prijevoda','Upload in progress — continue or cancel'=>'Prijenos u tijeku — nastavite ili otkažite','Scheduled, waiting to be processed'=>'Zakazano, čeka obradu','Translating…'=>'Prevođenje…','Translation failed'=>'Prevođenje nije uspjelo','Free quota used'=>'Besplatna kvota iskorištena','Needs a paid license'=>'Potrebna je plaćena licenca','Not supported'=>'Nije podržano','Status unknown'=>'Status nepoznat','translation statusInstalled'=>'Instalirano','Update available'=>'Ažuriranje dostupno','Removed after a failed integrity check'=>'Uklonjeno nakon neuspjele provjere cjelovitosti','Installed · built for %s, new version scheduled'=>'Instalirano · izrađeno za %s, nova verzija je zakazana','Installed · built for a different version, new version scheduled'=>'Instalirano · izrađeno za drugu verziju, nova verzija je zakazana','Installed · built for %s, translating the new version…'=>'Instalirano · izrađeno za %s, prevodi se nova verzija…','Installed · built for a different version, translating the new version…'=>'Instalirano · izrađeno za drugu verziju, prevodi se nova verzija…','Installed · built for %1$s, this site has %2$s'=>'Instalirano · izrađeno za %1$s, ova web-stranica ima %2$s','Installed · built for %s'=>'Instalirano · izrađeno za %s','Installed · built for a different version'=>'Instalirano · izrađeno za drugu verziju','Installed · built for %s, new version failed'=>'Instalirano · izrađeno za %s, nova verzija nije uspjela','Installed · built for a different version, new version failed'=>'Instalirano · izrađeno za drugu verziju, nova verzija nije uspjela','Installed · built for %s, new version needs a paid license'=>'Instalirano · izrađeno za %s, nova verzija zahtijeva plaćenu licencu','Installed · built for a different version, new version needs a paid license'=>'Instalirano · izrađeno za drugu verziju, nova verzija zahtijeva plaćenu licencu','Installed · built for %s, free quota used'=>'Instalirano · izrađeno za %s, besplatna kvota je iskorištena','Installed · built for a different version, free quota used'=>'Instalirano · izrađeno za drugu verziju, besplatna kvota je iskorištena','translation statusAvailable'=>'Dostupno','Installed · %s'=>'Instalirano · %s','Available · %s'=>'Dostupno · %s','Update'=>'Ažuriraj','Download'=>'Preuzmi','Updating…'=>'Ažuriranje…','Downloading…'=>'Preuzimanje…','Retry request'=>'Ponovi zahtjev','Request newer translation'=>'Zatraži noviji prijevod','Request translation'=>'Zatraži prijevod','Requesting…'=>'Traženje…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Traženje prijevoda koristi jedno od vaših slobodnih mjesta, osim ako ova komponenta već koristi jedno. Neuspjeli prijevod ne vraća mjesto.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Ako ova komponenta još ne koristi jedno od vaših slobodnih mjesta, traženje prijevoda koristi jedno. Neuspjeli prijevod ne vraća mjesto. Nastaviti?','No plugins or themes found.'=>'Nema pronađenih dodataka ili tema.','Clear filters'=>'Očisti filtre','No components match these filters. %s'=>'Nijedna komponenta ne odgovara ovim filtrima. %s','Select all'=>'Odaberi sve','All'=>'Sve','Available'=>'Dostupno','Updates'=>'Ažuriranja','Requestable'=>'Može se zatražiti','Installed'=>'Instalirano','Plugins'=>'Dodaci','Themes'=>'Teme','All languages'=>'Svi jezici','%d to install'=>'%d za instalaciju' . "\0" . '%d za instalaciju' . "\0" . '%d za instalaciju','Language:'=>'Jezik:','Bulk actions apply to every matching language of each selected component.'=>'Skupne radnje primjenjuju se na svaki odgovarajući jezik svake odabrane komponente.','Bulk actions apply only to the selected language of each selected component.'=>'Skupne radnje primjenjuju se samo na odabrani jezik svake odabrane komponente.','Version %s'=>'Verzija %s','Theme · %s'=>'Tema · %s','Plugin · %s'=>'Dodatak · %s','Remove the %2$s translation of %1$s from this site?'=>'Ukloniti prijevod %2$s za %1$s s ove web-stranice?','Roll back the %2$s translation of %1$s to the previous build?'=>'Vratiti prijevod %2$s za %1$s na prethodni build?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Izazov za registraciju nije u očekivanom obliku.','That is not a valid build identifier.'=>'To nije valjani identifikator builda.','Refusing to write outside the Babilim language-file directory.'=>'Odbijam pisanje izvan Babilim direktorija jezičnih datoteka.','Could not write the downloaded package to disk.'=>'Preuzeti paket nije moguće zapisati na disk.','Unexpected HTTP %d response.'=>'Neočekivani HTTP odgovor %d.','This site\'s URL, so the service can verify you own it.'=>'URL ove web-stranice, kako bi usluga mogla potvrditi da ste njezin vlasnik.','Your WordPress version, to serve compatible translation files.'=>'Vaša verzija WordPressa, radi isporuke kompatibilnih datoteka prijevoda.','Your PHP version, for compatibility.'=>'Vaša verzija PHP-a, radi kompatibilnosti.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Verzija ovog dodatka, kako bi vas usluga mogla uputiti da ga ažurirate ako je prestara za komunikaciju.','This site\'s configured locale.'=>'Konfigurirani jezični standard (locale) ove web-stranice.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Svaki jezik u uporabi na ovoj web-stranici (jezik web-stranice, instalirani jezični paketi, jezici korisnika i svi koje ručno dodate). Nijedan se jezik ne tretira drukčije od drugih.','(a public key generated for this site)'=>'(javni ključ generiran za ovu web-stranicu)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Javni ključ instalacije ove web-stranice, koji služi kao dokaz da zahtjevi doista dolaze s nje. Šalje se samo javni dio.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Svaki instalirani dodatak/tema: njegov slug, verzija, text domain(i), je li na popisu wp.org, vlastiti uključeni localei i za koje ste locale već instalirali Babilim prijevod.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Samo kada potvrdite prijenos dodatka ili teme koji nisu na WordPress.org: cijeli direktorij te komponente, kao zip.','(generic codes and coordinates only)'=>'(samo generički kodovi i koordinate)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Do 20 dijagnostičkih događaja na čekanju (npr. datoteka koja nije prošla provjeru cjelovitosti), svaki samo kao kod, komponenta i locale, a nikada sadržaj stringova ni prevedeni tekst.','Unsafe locale: %s'=>'Nesiguran locale: %s','Manifest unavailable: %s'=>'Manifest nije dostupan: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Nije moguće odrediti aktivne komponente; postojeći spojeni indeks ostavljen je nepromijenjen.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Nije moguće odrediti instalirane dodatke/teme; pretraživanje je preskočeno, ništa nije obrisano.','Sweep aborted without orphaning anything: %s.'=>'Pretraživanje je prekinuto bez ostavljanja ijedne datoteke bez vlasnika (osirotjele): %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Čišćenje je izvršeno, ali neke njegove promjene nije bilo moguće zabilježiti u indeksu prijevoda; sljedeće čišćenje pokušat će ih ponovno.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Spojeni indeks za \'%s\' ponovno je izgrađen, ali ga indeks prijevoda nije mogao zabilježiti; sljedeća izgradnja pokušat će ponovno.','Could not write the staged merged index.'=>'Nije moguće zapisati pripremljeni spojeni indeks.','Re-parsed entry count did not match the built index.'=>'Broj ponovno parsiranih unosa ne odgovara izgrađenom indeksu.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Nije moguće premjestiti spojeni indeks za \'%s\' na mjesto; prethodni poslužen indeks (ako je postojao) uklonjen je umjesto da ostane napola ažuriran. Za ovaj locale neće se posluživati dopuna default domene do sljedeće uspješne ponovne izgradnje.','Could not open zip: %s'=>'Nije moguće otvoriti zip: %s','Zip has no manifest.json.'=>'Zip nema manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json u zipu nije valjani JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'Polje \'%s\' u manifest.json ne odgovara očekivanoj vrijednosti.','Another installation is running; try again in a moment.'=>'Druga instalacija je u tijeku; pokušajte ponovno za trenutak.','Not a valid server_build_id: %s'=>'Nije valjani server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Vrsta \'%1$s\' u manifestu paketa ne odgovara zatraženoj vrsti \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Text domain paketa „%1$s” ne odgovara text domainu komponente na ovoj Web-stranici („%2$s”), pa paket nije instaliran.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Zadana domena \'%1$s\' ne odgovara ni slugu \'%2$s\' iz manifesta paketa ni njegovu text_domain \'%3$s\'.','Unsafe slug: %s'=>'Nesiguran slug: %s','Unsafe text_domain: %s'=>'Nesiguran text_domain: %s','The package has no %s for its own text domain.'=>'Paket nema %s za vlastitu text domain.','manifest.json is missing or has an invalid \'%s\'.'=>'U datoteci manifest.json polje \'%s\' nedostaje ili nije valjano.','manifest.json is missing or has an invalid \'entries\'.'=>'U datoteci manifest.json polje \'entries\' nedostaje ili nije valjano.','manifest.json is missing or has an invalid \'files\'.'=>'U datoteci manifest.json polje \'files\' nedostaje ili nije valjano.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'U datoteci manifest.json polje \'extra_domains\' nedostaje ili nije valjano.','manifest.json is missing or has an invalid \'build_no\'.'=>'U datoteci manifest.json polje \'build_no\' nedostaje ili nije valjano.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' u manifest.json nije valjani ID builda.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' u manifest.json nije valjani niz verzije.','manifest.json\'s \'status\' must be \'published\'.'=>'\'status\' u manifest.json mora biti \'published\'.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' u manifest.json mora biti \'plugin\' ili \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ima neispravno polje \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ima neispravno polje \'default_domain_files\'.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest nedostaje ili ima neispravno polje \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' u expected_manifest nije valjani ID builda.','No record for %s'=>'Nema zapisa za %s','One or more served files no longer match the manifest.'=>'Jedna ili više poslužitelj­skih datoteka više se ne podudara s manifestom.','No previous build to roll back to.'=>'Nema prethodnog builda na koji bi se vratilo.','The change could not be recorded in the translation index; please try again.'=>'Promjenu nije moguće zabilježiti u indeksu prijevoda; pokušajte ponovno.','Unknown kind: %s'=>'Nepoznata vrsta: %s','Unsafe domain: %s'=>'Nesigurna domena: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'The text domain \'%1$s\' (%2$s) već se poslužuje za drugu instaliranu komponentu (%3$s); ništa nije instalirano.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Vraćanje bi prepisalo \'%1$s\' (%2$s), koja se sada poslužuje za drugu instaliranu komponentu (%3$s); ništa nije promijenjeno.','Zip is missing expected file: %s'=>'U zip datoteci nedostaje očekivana datoteka: %s','sha256 mismatch for %s'=>'sha256 se ne podudara za %s','The package declares no main translation file.'=>'Paket ne deklarira glavnu datoteku prijevoda.','Zip is missing expected default file: %s'=>'U zip datoteci nedostaje očekivana zadana datoteka: %s','sha256 mismatch for default/%s'=>'sha256 se ne podudara za default/%s','Could not stage %s'=>'Nije moguće pripremiti %s','Could not stage default/%s'=>'Nije moguće pripremiti default/%s','Entry count mismatch for %s'=>'Broj unosa se ne podudara za %s','Could not verify entry count for %s'=>'Nije moguće provjeriti broj unosa za %s','l10n.php entry count mismatch for %s'=>'Broj unosa u l10n.php se ne podudara za %s','Default supplement entry count mismatch.'=>'Broj unosa zadanog dodatka se ne podudara.','The package produced no servable main translation file.'=>'Paket nije proizveo glavnu datoteku prijevoda koja se može poslužiti.','Could not prepare %s for rollback.'=>'Nije moguće pripremiti %s za vraćanje.','Could not back up %s before replacing it.'=>'Nije moguće napraviti sigurnosnu kopiju %s prije zamjene.','Could not move %s into place.'=>'Nije moguće premjestiti %s na mjesto.','English (United States)'=>'engleski (Sjedinjene Američke Države)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest nije dostupan: %s','could not read _manifest.json: %s'=>'nije moguće pročitati _manifest.json: %s','failed to parse _manifest.json: %s'=>'nije uspjelo parsiranje datoteke _manifest.json: %s','_manifest.json has an unexpected structure'=>'Datoteka _manifest.json ima neočekivanu strukturu','Could not create the package archive.'=>'Nije moguće izraditi arhivu paketa.','No writable temporary directory is available for packaging.'=>'Nije dostupan direktorij za privremene datoteke u koji se može pisati za pakiranje.','A file in the component could not be read, so it was not packaged.'=>'Datoteka u komponenti nije se mogla pročitati, pa nije spakirana.','Only plugins and themes can be packaged.'=>'Mogu se pakirati samo dodaci i teme.','The component\'s main file was not found.'=>'Glavna datoteka komponente nije pronađena.','The component is not inside the plugins or themes directory.'=>'Komponenta se ne nalazi u direktoriju dodataka ili tema.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilimu je za ovaj korak isteklo vrijeme i nastavit će pri sljedećoj provjeri.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nije mogao potvrditi ovu web-stranicu, pa se ništa neće preuzeti niti instalirati dok potvrda ne uspije.','Registration response was missing required fields.'=>'Odgovoru na registraciju nedostajala su obavezna polja.','No pending challenge to verify.'=>'Nema izazova na čekanju za potvrdu.','Verify response was missing site_token.'=>'Odgovoru na potvrdu nedostajao je site_token.','No site id is on file to rotate a token for.'=>'Nema spremljenog ID-a web-stranice za koji bi se rotirao token.','Rotate-token response was missing site_token.'=>'Odgovoru na rotaciju tokena nedostajao je site_token.','nonce must be a hexadecimal string.'=>'nonce mora biti heksadecimalni niz.','No pending challenge for this nonce.'=>'Nema izazova na čekanju za ovaj nonce.','Too many requests.'=>'Previše zahtjeva.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Ova web-stranica ima %1$d komponenti na %2$d jezika, što zahtijeva %3$d serija provjere; Babilim može obraditi najviše %4$d po pokretanju. Smanjite broj upravljanih jezika u Postavkama ili deaktivirajte nekorištene dodatke i teme, a zatim sada ponovno pritisnite Provjeri.','Babilim could not finish checking this site.'=>'Babilim nije mogao dovršiti provjeru ove web-stranice.','This site\'s address is too long for Babilim to register.'=>'Adresa ove web-stranice predugačka je da bi je Babilim registrirao.','This site\'s locale code is not one Babilim can register.'=>'Kôd jezika ove web-stranice nije takav da ga Babilim može registrirati.','The download response was missing a usable location.'=>'Odgovoru na preuzimanje nedostajala je upotrebljiva lokacija.','The service\'s upload offer was incomplete.'=>'Ponuda usluge za prijenos bila je nepotpuna.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ova komponenta veća je nego što usluga prihvaća, pa se ne može prenijeti.','The packaged component could not be read.'=>'Spakirana komponenta nije se mogla pročitati.','A part of the upload kept failing, so the upload was cancelled.'=>'Dio prijenosa stalno nije uspijevao, pa je prijenos otkazan.','Could not read: %s'=>'Nije moguće pročitati: %s']];